import React from 'react';
import '../styles/ComfortSection.css';

const ComfortSection = () => {
  const rooms = [
    { id: 1, name: 'Коридор', img: `${process.env.PUBLIC_URL}/imgg/Frame 12.png` },
    { id: 2, name: 'Кухня', img: `${process.env.PUBLIC_URL}/imgg/Frame 11.png` },
    { id: 3, name: 'Балкон і сад', img: `${process.env.PUBLIC_URL}/imgg/Frame 14.png` },
    { id: 4, name: 'Спальня', img: `${process.env.PUBLIC_URL}/imgg/Frame 10.png` },
    { id: 5, name: 'Вітальня', img: `${process.env.PUBLIC_URL}/imgg/Frame 13.png` },
    { id: 6, name: 'Ванна кімната', img: `${process.env.PUBLIC_URL}/imgg/Frame 15.png` }
  ];

  return (
    <section className="comfort-section">
      <div className="comfort-header">
        <h2>Втілення затишку</h2>
        <a href="#" className="all-btn">Усе</a>
      </div>
      <div className="comfort-grid">
        {rooms.map(room => (
          <div key={room.id} className="comfort-card">
            <img src={room.img} alt={room.name} />
            <div className="comfort-card-content">
              <span>{room.name}</span>
              <span className="arrow">→</span>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
};

export default ComfortSection;
